import { parse, stringify } from "./src/index.js";

// U+11000 = BRAHMI SIGN ANUSVARA
// This is ID_Continue (can follow an identifier) but NOT ID_Start
const astralContinue = String.fromCodePoint(0x11000);
console.log("Astral char:", astralContinue);
console.log("Code point: U+11000");

const ID_CONTINUE = /^[$\u200c\u200d\p{ID_Continue}]$/u;
console.log("ID_CONTINUE matches:", ID_CONTINUE.test(astralContinue));
console.log("ID_CONTINUE matches [0]:", ID_CONTINUE.test(astralContinue[0]));

// The bug: parse `:foo` followed by text starting with astral ID_Continue
// Since U+11000 is NOT ID_Start, the parser correctly creates:
//   param "foo" + text "𝌀"
// But stringify should quote "foo" to prevent parse from merging them on re-parse
const path = `:foo${astralContinue}`;
console.log("\n=== Input ===");
console.log("Path:", path);

const parsed = parse(path);
console.log("\n=== Parse result ===");
console.log("Tokens:", JSON.stringify(parsed.tokens));

const stringified = stringify(parsed);
console.log("\n=== Stringify result ===");
console.log("Stringified:", stringified);

// The bug: stringified should be :foo"𝌀" (quoted param) but is :foo𝌀 (unquoted)
// because stringifyName checks next.value[0] which is a lone surrogate, failing the regex

console.log("\n=== Round-trip test ===");
console.log("Expected: :foo\"𝌀\" (quoted param name)");
console.log("Got:     ", stringified);

try {
  const reparsed = parse(stringified);
  console.log("Reparsed tokens:", JSON.stringify(reparsed.tokens));

  const origParam = parsed.tokens.find((t: any) => t.type === "param");
  const reParam = reparsed.tokens.find((t: any) => t.type === "param");

  console.log("\nOriginal param name:", origParam?.name);
  console.log("Reparsed param name:", reParam?.name);

  if (origParam?.name !== reParam?.name) {
    console.log("\n*** BUG CONFIRMED: Round-trip breaks param name! ***");
    process.exit(1);
  } else {
    console.log("\nRound-trip OK");
  }
} catch (e) {
  console.error("Reparse failed:", e);
  console.log("\n*** BUG CONFIRMED: Round-trip breaks parsing! ***");
  process.exit(1);
}

